    if (
        not isinstance(marker_size_mm, Real)
        or isinstance(marker_size_mm, bool)
        or not math.isfinite(float(marker_size_mm))
        or float(marker_size_mm) <= 0
    ):
        raise ValueError('marker_size_mm must be a finite positive number')
